pub fn ctxRef(comptime T: type, ctx: ?*anyopaque) ?*T {
        if ((ctx == null)) {
            return null;
        }
        return (blk: {
        break :blk @as(*T, @ptrCast(@alignCast(ctx.?)));

});
}

pub fn globalInit() void {
        _ = lsquic_global_init((LSQUIC_GLOBAL_CLIENT | LSQUIC_GLOBAL_SERVER));
}

pub fn enableLogging(level: [*:0]const u8) void {
        _ = us_nq_enable_logging(level);
}
